/* Aplicación estática. Sin cuentas, servicios externos ni claves. */
'use strict';
const R=window.Rules,KEY='darien-voss-2014-v1',BACKUP=KEY+'-previous';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const sign=n=>(n>=0?'+':'')+n,uid=()=>crypto.randomUUID?crypto.randomUUID():'id'+Date.now()+Math.random().toString(36).slice(2),clone=o=>JSON.parse(JSON.stringify(o));
let state=R.initial(),view='combat',history=[],query='',filter='all',storageIssue='',rawBroken=null,toastTimer;
try{const raw=localStorage.getItem(KEY);if(raw){try{state=R.validate(JSON.parse(raw));}catch(e){rawBroken=raw;storageIssue='No se pudo leer la ficha guardada. Podés descargar el contenido desde Mi ficha antes de reemplazarlo.';}}}catch(e){storageIssue='El navegador no permite guardar aquí. Exportá una copia antes de cerrar.';}
const navs=[['combat','◈','Combate'],['spells','✦','Conjuros'],['gear','▣','Equipo'],['character','◇','Personaje'],['journal','≡','Diario']];
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4200);}
function persist(before){try{if(rawBroken)throw Error('Resguardá o reemplazá la ficha dañada desde Mi ficha.');if(before)localStorage.setItem(BACKUP,JSON.stringify(before));localStorage.setItem(KEY,JSON.stringify(state));$('#save-status').textContent='Guardado en este dispositivo';storageIssue='';}catch(e){storageIssue=rawBroken?e.message:'No se pudo guardar. Tu ficha sigue abierta: exportá una copia.';$('#save-status').textContent='Sin guardar';toast(storageIssue);}}
function commit(label,fn){const before=clone(state),next=clone(state);try{fn(next);next.log.unshift({date:new Date().toISOString(),text:label});next.log=next.log.slice(0,100);R.validate(next);}catch(e){throw Error(e.message||'No se pudo aplicar el cambio.');}history.push(before);history=history.slice(-20);state=next;persist(before);render();}
function download(name,data,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function roll(sides,count=1){const a=[];for(let i=0;i<count;i++){let x;const limit=Math.floor(4294967296/sides)*sides;do{x=crypto.getRandomValues(new Uint32Array(1))[0];}while(x>=limit);a.push(x%sides+1);}return a;}
function number(fd,key,min,max,def){const raw=fd.get(key);if((raw===null||raw==='')&&def!==undefined)return def;const n=Number(raw);if(raw===''||!Number.isFinite(n)||!Number.isInteger(n)||n<min||n>max)throw Error('Revisá «'+key+'»: usá un entero entre '+min+' y '+max+'.');return n;}
function field(label,name,value='',type='text',extra=''){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function select(label,name,options,value){return `<label class="field">${label}<select name="${name}">${options.map(([v,t])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`;}
function area(label,name,value){return `<label class="field">${label}<textarea name="${name}">${esc(value)}</textarea></label>`;}
function modal(title,html,submit,saveLabel='Guardar'){const d=$('#modal');if(d.open)d.close();$('#modal-content').innerHTML=`<div class="modal-head"><h2 id="dialog-title">${esc(title)}</h2><button type="button" class="icon-btn" data-close aria-label="Cerrar">×</button></div><form id="dialog-form"><div class="modal-body">${html}<p class="form-error" id="form-error" role="alert"></p>${submit?`<div class="modal-actions"><button type="button" class="button secondary" data-close>Cancelar</button><button class="button" type="submit">${esc(saveLabel)}</button></div>`:''}</div></form>`;$('#dialog-form').addEventListener('submit',e=>{e.preventDefault();if(!submit)return;try{submit(new FormData(e.currentTarget));d.close();}catch(err){$('#form-error').textContent=err.message;}});d.showModal();}
function confirmAction(title,text,fn,label='Confirmar'){modal(title,`<p>${esc(text)}</p>`,()=>fn(),label);}
function header(title,subtitle,buttons=''){return `<div class="heading"><div><p class="eyebrow">${view==='combat'?'EN LA MESA':'CUADERNO DE DARIEN'}</p><h1>${title}</h1><p>${subtitle}</p></div><div class="actions">${buttons}</div></div>`;}
function button(label,action,classes='secondary',data=''){return `<button type="button" class="button ${classes}" data-action="${action}" ${data}>${label}</button>`;}
function poolValue(s,type,index){if(type==='slot')return s.slotsSpent[index];if(type==='inspiration')return s.inspirationSpent;if(type==='hd')return s.hdSpent;if(type==='universal')return s.universalSpent;if(type==='infectious')return s.infectiousSpent;return s.extraResources.find(x=>x.id===index)?.spent;}
function poolMax(s,type,index){const d=R.stats(s);return type==='slot'?d.slots[index]||0:type==='inspiration'||type==='infectious'?d.inspirationMax:type==='hd'?s.level:type==='universal'?1:s.extraResources.find(x=>x.id===index)?.max||0;}
function setPool(s,type,index,value){if(type==='slot')s.slotsSpent[index]=value;else if(type==='inspiration')s.inspirationSpent=value;else if(type==='hd')s.hdSpent=value;else if(type==='universal')s.universalSpent=value;else if(type==='infectious')s.infectiousSpent=value;else s.extraResources.find(x=>x.id===index).spent=value;}
function pool(title,type,index='',help=''){const max=poolMax(state,type,index),used=poolValue(state,type,index);return `<div class="pool-row"><div class="pool-head"><span>${title}</span><button class="text-btn" data-action="pool-edit" data-type="${type}" data-index="${esc(index)}"><strong>${used===null?'—':max-used} / ${max}</strong></button></div><div class="pips">${Array.from({length:max},(_,i)=>`<button class="pip ${used===null?'unknown':i<used?'spent':''}" data-action="pip" data-type="${type}" data-index="${esc(index)}" data-pip="${i}" aria-label="${esc(title)}: ${used===null?'ajustar cantidad':i<used?'recuperar un uso':'gastar un uso'}">${used===null?'?':i<used?'−':'✦'}</button>`).join('')}</div>${help?`<div class="pool-help">${help}</div>`:''}</div>`;}
function spellById(id){return R.allSpells(state).find(s=>s.id===id);}
function spellName(id){return spellById(id)?.name||'Conjuro';}
function missing(){return R.stats(state).known-state.known.filter(id=>spellById(id)?.level>0).length;}
function combat(){const d=R.stats(state);return header('Que empiece la aventura.',`${esc(state.name)} · Bardo ${state.level}${state.level>=3&&state.subclass==='eloquence'?' de Elocuencia':''}`,button('Descansar','rest')+button('Subir de nivel','levelup',''))+
`${!state.hpConfirmed||state.hp===null||state.inspirationSpent===null||state.slotsSpent[0]===null?`<div class="banner"><p><b>Antes de continuar:</b> confirmá tus PG y los recursos que te quedan de la sesión.</p>${button('Ajustar recursos','resources')}</div>`:''}`+
`<div class="metrics"><div class="metric"><strong>${d.ac}</strong><span>Armadura</span></div><div class="metric"><strong>${sign(d.initiative)}</strong><span>Iniciativa</span></div><div class="metric"><strong>${d.dc}</strong><span>CD conjuros</span></div><div class="metric"><strong>30</strong><span>Pies / turno</span></div></div><div class="grid combat-grid"><div class="stack"><section class="card"><div class="card-header"><h2>Puntos de golpe</h2><button class="text-btn" data-action="resources">Ajustar</button></div><div class="hp-number">${state.hp===null?'—':state.hp}<small> / ${d.maxHP}${!state.hpConfirmed?'*':''}</small></div><div class="meter"><span style="width:${state.hp===null?0:100*state.hp/d.maxHP}%"></span></div><div class="inline"><span class="tag">${state.temp} PG temporales</span>${!state.hpConfirmed?'<small>*Máximo previsto con aumento fijo</small>':''}</div><div class="hp-controls"><label class="visually-hidden" for="hp-amount">Cantidad de daño o curación</label><input class="control" id="hp-amount" type="number" min="1" max="9999" value="1"><button class="button danger" data-action="damage">Daño</button><button class="button secondary" data-action="heal">Curar</button></div><button class="text-btn" data-action="temp">PG temporales</button>${state.hp===0?`<div class="divider"></div><h3>Salvaciones de muerte</h3><p class="small">Ajustá los fallos manualmente si recibís un crítico (2). El daño masivo puede causar muerte instantánea: confirmalo con el DM.</p><div class="inline"><button class="button secondary" data-action="death" data-kind="success">Éxitos ${state.death.success}/3</button><button class="button danger" data-action="death" data-kind="failure">Fallos ${state.death.failure}/3</button><button class="text-btn" data-action="death-reset">Reiniciar</button></div>${state.death.failure===3?'<p class="error">Tres fallos: muerte. Confirmá el resultado con el DM.</p>':state.death.success===3?'<p>Estabilizado: seguís a 0 PG.</p>':''}`:''}</section><section class="card"><div class="card-header"><h2>A mano</h2>${button('Tirar dados','dice')}</div>${[['Estoque',d.mods.dex+d.prof,`1d8 ${sign(d.mods.dex)} perforante · 5 pies`],['Daga',d.mods.dex+d.prof,`1d4 ${sign(d.mods.dex)} perforante · 20/60 arrojada`],['Iniciativa',d.initiative,'Prueba de Destreza + Aprendiz de mucho']].map(([name,n,desc])=>`<div class="attack-row"><div><b>${name}</b><p>${desc}</p></div><button class="roll-button" data-action="roll" data-bonus="${n}" data-label="${name}">d20 ${sign(n)}</button></div>`).join('')}<div class="attack-row"><div><b>Burla dañina</b><p>${state.level>=17?4:state.level>=11?3:state.level>=5?2:1}d4 psíquico · SAB CD ${d.dc}</p></div><button class="text-btn" data-action="spell-open" data-id="mockery">Ver</button></div></section></div><div class="stack"><section class="card"><div class="card-header"><h2>Tu reserva</h2><span class="tag">Nivel ${state.level}</span></div>${d.slots.map((_,i)=>pool('Espacios de nivel '+(i+1),'slot',i,i===0?'Tocá un símbolo para gastar o recuperar.':'')).join('')}${pool('Inspiración · d'+d.inspirationDie,'inspiration','',state.level>=5?'Vuelve con descanso corto o largo.':'Vuelve con descanso largo.')}${pool('Dados de Golpe · d8','hd')}${state.level>=6&&state.subclass==='eloquence'?pool('Discurso universal','universal'):''}${state.level>=14&&state.subclass==='eloquence'?pool('Inspiración contagiosa','infectious'):''}${state.extraResources.map(x=>pool(esc(x.name),'extra',x.id)).join('')}</section><section class="card"><div class="card-header"><h2>En curso</h2><button class="text-btn" data-action="turn">Mi turno</button></div><div class="list-row"><div><b>Reacción</b><p>Se recupera al empezar tu turno.</p></div><button class="chip ${state.reactionUsed?'selected':''}" data-action="reaction">${state.reactionUsed?'Gastada':'Disponible'}</button></div><div class="list-row"><div><b>Concentración</b><p>${state.concentration?esc(spellName(state.concentration)):'Ninguna'}</p></div>${state.concentration?button('Terminar','concentration-end'):''}</div><h3 class="section-space">Condiciones</h3><div class="chips">${['Derribado','Asustado','Hechizado','Envenenado','Incapacitado','Inconsciente','Agarrado','Restringido','Cegado','Ensordecido','Paralizado','Aturdido','Invisible','Petrificado'].map(c=>`<button class="chip ${state.conditions.includes(c)?'selected':''}" data-action="condition" data-condition="${c}" aria-pressed="${state.conditions.includes(c)}">${c}</button>`).join('')}</div></section></div></div>`;}
function spellCard(s){const extra=state.extras.includes(s.id);return `<details class="spell" id="spell-${esc(s.id)}"><summary><div class="spell-title"><div><h2>${esc(s.name)}</h2><div class="spell-meta">${s.level?'Nivel '+s.level:'Truco'} · ${esc(s.time)} · ${esc(s.range)}</div></div>${extra?'<span class="tag">Extra DM</span>':s.concentration?'<span class="tag">Conc.</span>':''}</div><p class="spell-brief">${esc(s.brief)}</p></summary><div class="spell-body"><p>${esc(s.text)}</p><p class="small">Componentes: ${esc(s.components)}<br>Duración: ${esc(s.duration)}${s.concentration?' · Concentración':''}<br>Fuente: ${esc(s.source)}</p><div class="spell-footer">${button(s.level?'Lanzar':'Usar truco','cast','',`data-id="${esc(s.id)}"`)}${s.ritual?button('Ritual · sin espacio','ritual','secondary',`data-id="${esc(s.id)}"`):''}${button('Editar','spell-edit','secondary',`data-id="${esc(s.id)}"`)}</div></div></details>`;}
function spellPage(){let list=[...state.known,...state.extras].map(spellById).filter(Boolean).filter(s=>(filter==='all'||filter==='ritual'&&s.ritual||filter==='concentration'&&s.concentration||filter==='reaction'&&s.time==='Reacción')&&s.name.toLowerCase().includes(query.toLowerCase()));list.sort((a,b)=>a.level-b.level||a.name.localeCompare(b.name));let d=R.stats(state);return header('Tu repertorio.',`CD ${d.dc} · Ataques ${sign(d.attack)} · ${state.known.filter(id=>spellById(id)?.level>0).length}/${d.known} conjuros de bardo + ${state.extras.length} adicional del DM`,button('Gestionar conjuros','spell-manage')+button('Crear conjuro','spell-new',''))+`${missing()>0?`<div class="banner"><p>Te falta elegir ${missing()} conjuro${missing()>1?'s':''}. Silvery Barbs está disponible en el catálogo; Detectar magia no ocupa esta elección.</p>${button('Elegir','spell-manage')}</div>`:''}<div class="toolbar"><input class="control" id="spell-search" type="search" placeholder="Buscar en tus conjuros…" aria-label="Buscar conjuros" value="${esc(query)}"><select class="control" id="spell-filter" aria-label="Filtrar conjuros">${[['all','Todos'],['concentration','Concentración'],['ritual','Rituales'],['reaction','Reacciones']].map(([v,t])=>`<option value="${v}" ${v===filter?'selected':''}>${t}</option>`).join('')}</select></div><div class="spell-grid">${list.length?list.map(spellCard).join(''):'<div class="empty">No hay conjuros con ese filtro.</div>'}</div>`;}
function gear(){const total=state.gold.cp+state.gold.sp*10+state.gold.ep*50+state.gold.gp*100+state.gold.pp*1000;const weight=state.inventory.reduce((a,x)=>a+(x.weight||0)*x.qty,0);return header('Cada cosa en su lugar.','Equipo, provisiones y cuentas del viaje.',button('Añadir objeto','item-new',''))+`<div class="columns gear-columns"><section class="card"><div class="card-header"><h2>Inventario</h2><small>${state.inventory.length} entradas</small></div><div class="inventory-list">${state.inventory.map(x=>`<div class="list-row"><div><button class="text-btn item-name" data-action="item-edit" data-id="${esc(x.id)}">${esc(x.name)}</button><p>${esc(x.category)} · ${esc(x.location)}</p></div><div class="qty"><button class="icon-btn" aria-label="Restar ${esc(x.name)}" data-action="qty" data-id="${esc(x.id)}" data-delta="-1" ${x.qty===0?'disabled':''}>−</button><span>${x.qty}</span><button class="icon-btn" aria-label="Sumar ${esc(x.name)}" data-action="qty" data-id="${esc(x.id)}" data-delta="1">+</button></div></div>`).join('')}</div><p class="small section-space">Peso registrado: ${weight.toFixed(1)} lb. Solo suma objetos con peso informado; no es la carga total. Capacidad normal de Darien: ${state.abilities.str*15} lb.</p></section><div class="stack"><section class="card"><div class="card-header"><h2>La bolsa</h2><button class="text-btn" data-action="gold-edit">Editar saldo</button></div><div class="coin-grid">${[['cp','pc'],['sp','pp'],['ep','pe'],['gp','po'],['pp','ppt']].map(([k,l])=>`<div class="coin"><strong>${state.gold[k]}</strong><span class="small">${l}</span></div>`).join('')}</div><p class="small section-space">Equivalente: ${(total/100).toLocaleString('es-AR',{maximumFractionDigits:2})} po. ${state.goldConfirmed?'':'Saldo inicial de 15 po; confirmá gastos y recompensas.'}</p><div class="actions">${button('Ingreso / gasto','gold-transaction','')}</div></section><section class="card"><div class="card-header"><h2>${esc(state.mule.name)}</h2><span class="tag">CA 10</span></div><div class="hp-number" style="font-size:2.8rem">${state.mule.hp??'—'}<small> / ${state.mule.max} PG</small></div><p class="small section-space">40 pies · Iniciativa +0 · Mediana<br>Pezuñas +2 · 1d4 + 2 contundente<br>Paso firme: ventaja FUE/DES contra derribo.</p><p class="small">Carga: 420 lb. Con carro: 2.100 lb incluido el carro. El DM maneja su conducta; no es un ataque adicional automático. Darien puede ir en el carro; la mula no es de un tamaño mayor que él.</p>${button('Editar mula','mule')}</section><section class="card"><h2>Comerciante gremial</h2><p class="small">Cuota: 5 po al mes. Herramientas de navegante: competencia confirmada, juego físico por confirmar. No se añadieron raciones, cuerda ni otros objetos que no tuvieras.</p></section></div></div>`;}
function character(){const d=R.stats(state);return header('La ficha de Darien.',`Semielfo · Bardo ${state.level} · ${state.level>=3?(state.subclass==='eloquence'?'Colegio de la Elocuencia':'Subclase manual'):'Colegio en nivel 3'}`,button('Editar características','stats')+button('Subir de nivel','levelup',''))+`<div class="ability-grid">${Object.entries(R.attrs).map(([k,label])=>`<section class="card ability-box"><span>${label}</span><strong>${sign(d.mods[k])}</strong><span>Puntuación ${state.abilities[k]}</span></section>`).join('')}</div><div class="grid two section-space"><section class="card"><h2>Habilidades</h2><div class="skill-list">${R.skills.map(([id,name])=>`<div class="list-row"><span>${esc(name)}${state.expertise.includes(id)?' ◆':state.proficiencies.includes(id)?' •':''}</span><button class="roll-button" data-action="skill-roll" data-id="${id}">${sign(R.skillBonus(state,id))}</button></div>`).join('')}</div><p class="small section-space">• Competencia · ◆ Pericia. Todos los bonos ya están incluidos. Percepción pasiva: ${10+R.skillBonus(state,'perception')}.</p></section><section class="card"><h2>Salvaciones</h2>${Object.entries(R.attrs).map(([k,label])=>`<div class="list-row"><span>${label}</span><button class="roll-button" data-action="roll" data-label="Salvación de ${label}" data-bonus="${R.saveBonus(state,k)}">${sign(R.saveBonus(state,k))}</button></div>`).join('')}<div class="divider"></div><h3>Idiomas y competencias</h3><p class="small">Común, Élfico, Enano y Gnómico. Armaduras ligeras. Armas simples, ballesta de mano, espada larga, estoque y espada corta. Flauta, laúd, viola y herramientas de navegante.</p></section></div><section class="card section-space"><div class="card-header"><h2>Lo que podés hacer</h2>${button('Rasgo personalizado','feature-new')}</div>${R.features(state).map(([name,text])=>`<div class="feature"><h3>${esc(name)}</h3><p>${esc(text)}</p></div>`).join('')}${state.features.length?button('Editar rasgos propios','feature-manage'):''}</section>`;}
function journal(){return header('El viaje continúa.','Notas, compañeros e historial de cambios.',button('Exportar copia','backup'))+`<div class="columns"><div class="stack"><section class="card"><h2>Notas de la sesión</h2><label class="field"><span class="visually-hidden">Notas</span><textarea id="journal-notes" style="min-height:230px">${esc(state.notes)}</textarea></label>${button('Guardar notas','notes-save','')}</section><section class="card"><div class="card-header"><h2>Compañera de viaje</h2><button class="text-btn" data-action="companion">Editar</button></div><div class="companion"><img src="./assets/companion.webp" alt="Referencia de la esposa elfa de Darien" width="768" height="1152"><div><h3>${esc(state.companion.name)}</h3><p>${esc(state.companion.notes)}</p></div></div></section><section class="card"><h2>Progresión registrada</h2>${state.levelHistory.length?state.levelHistory.map(x=>`<div class="feature"><h3>Nivel ${x.level}</h3><p>${esc(x.note)}</p></div>`).join(''):'<p class="muted">La ficha comienza en bardo 2. Las próximas subidas quedarán acá.</p>'}</section></div><section class="card"><div class="card-header"><h2>Últimos cambios</h2><button class="text-btn" data-action="undo">Deshacer</button></div><div class="log">${state.log.length?state.log.slice(0,40).map(x=>`<div class="log-item"><time>${esc(new Date(x.date).toLocaleString('es-AR'))}</time><p>${esc(x.text)}</p></div>`).join(''):'<p class="muted">Los gastos, descansos y cambios de la ficha se registrarán acá.</p>'}</div></section></div>`;}
function render(){const y=scrollY;$('#nav').innerHTML=navs.map(([id,icon,label])=>`<a class="nav-link ${view===id?'active':''}" href="#${id}" ${view===id?'aria-current="page"':''}><span class="nav-symbol" aria-hidden="true">${icon}</span><span>${label}</span></a>`).join('');$('#breadcrumb').textContent=navs.find(x=>x[0]===view)?.[2]||'Combate';$('#main').innerHTML=(storageIssue?`<div class="banner"><p>${esc(storageIssue)}</p>${button('Mi ficha','settings')}</div>`:'')+({combat,spells:spellPage,gear,character,journal}[view]||combat)();scrollTo(0,y);}
function go(){view=location.hash.slice(1);if(!navs.some(x=>x[0]===view))view='combat';query='';filter='all';render();scrollTo(0,0);}
function editResources(){let d=R.stats(state);modal('Recursos actuales',`<p class="small">Ingresá lo que te queda ahora. El máximo de PG sugerido (${d.maxHP}) usa los aumentos fijos hasta nivel ${state.level} salvo ajustes previos.</p><div class="form-grid">${field('PG máximos','máximo',d.maxHP,'number','min="1" max="2000" required')}${field('PG actuales','PG',state.hp??'','number','min="0" max="2000" required')}${field('PG temporales','temporales',state.temp,'number','min="0" max="9999" required')}${field('Inspiraciones disponibles','inspiración',state.inspirationSpent===null?'':d.inspirationMax-state.inspirationSpent,'number',`min="0" max="${d.inspirationMax}" required`)}${field('Dados de Golpe disponibles','dados',state.hdSpent===null?'':state.level-state.hdSpent,'number',`min="0" max="${state.level}" required`)}${d.slots.map((max,i)=>field('Espacios disponibles de nivel '+(i+1),'slot'+i,state.slotsSpent[i]===null?'':max-state.slotsSpent[i],'number',`min="0" max="${max}" required`)).join('')}</div>`,fd=>{const max=number(fd,'máximo',1,2000),hp=number(fd,'PG',0,max);commit('Ajuste de recursos actuales',s=>{s.hpBase=max-s.level*d.mods.con;s.hp=hp;s.hpConfirmed=true;s.temp=number(fd,'temporales',0,9999);s.inspirationSpent=d.inspirationMax-number(fd,'inspiración',0,d.inspirationMax);s.hdSpent=s.level-number(fd,'dados',0,s.level);d.slots.forEach((n,i)=>s.slotsSpent[i]=n-number(fd,'slot'+i,0,n));});});}
function editPool(type,index){let max=poolMax(state,type,index),used=poolValue(state,type,index);modal('Ajustar usos',field('Usos disponibles','usos',used===null?'':max-used,'number',`min="0" max="${max}" required`),fd=>commit('Ajuste de usos disponibles',s=>setPool(s,type,index,max-number(fd,'usos',0,max))));}
function cast(id,ritual=false){let sp=spellById(id);if(!sp||(!state.known.includes(id)&&!state.extras.includes(id)))throw Error('Este conjuro no está entre tus conocidos.');if(ritual&&!sp.ritual)throw Error('No es ritual.');const d=R.stats(state),eligible=d.slots.map((max,i)=>[i+1,`Nivel ${i+1} · ${state.slotsSpent[i]===null?'sin confirmar':max-state.slotsSpent[i]} disponibles`]).filter(([l])=>l>=sp.level);let html=`<p>${esc(sp.brief)}</p><p class="small">${esc(sp.time)} · ${esc(sp.components)}${ritual?' · Ritual: añade 10 minutos al lanzamiento.':''}</p>`;if(sp.level&&!ritual){if(!eligible.length)throw Error('Todavía no tenés espacios de ese nivel.');html+=select('Espacio a gastar','espacio',eligible,eligible[0][0]);}if(sp.time==='Reacción'&&state.reactionUsed&&!ritual)throw Error('Tu reacción ya está gastada. Recuperala al empezar tu turno.');if(sp.concentration||ritual)html+=`<div class="banner"><p>${state.concentration?'Reemplaza tu concentración en '+esc(spellName(state.concentration))+'.':'Requiere concentración.'}</p></div>`;if(sp.id==='silvery')html+='<label class="check"><input type="checkbox" name="válido" required>Confirmo que una criatura visible tuvo éxito y puedo usar esta reacción (no lancé un conjuro de acción adicional en este mismo turno).</label>';modal(ritual?'Lanzamiento ritual':sp.name,html,fd=>{let slot=sp.level&&!ritual?number(fd,'espacio',sp.level,9):0;if(slot&&(state.slotsSpent[slot-1]===null))throw Error('Confirmá primero cuántos espacios te quedan en Combate.');if(slot&&(state.slotsSpent[slot-1]>=d.slots[slot-1]))throw Error('No quedan espacios de ese nivel.');commit((ritual?'Ritual: ':'Lanzado: ')+sp.name+(slot?' · espacio '+slot:''),s=>{if(slot)s.slotsSpent[slot-1]++;if(sp.time==='Reacción'&&!ritual)s.reactionUsed=true;if(sp.concentration||ritual)s.concentration=sp.id;});toast(ritual?'Ritual iniciado. Controlá su tiempo de lanzamiento en mesa.':'Recurso registrado. Resolvé el efecto y las tiradas en mesa.');},ritual?'Iniciar ritual':'Registrar lanzamiento');}
function spellManage(){const d=R.stats(state),list=R.allSpells(state).filter(x=>x.level<=d.slots.length);modal('Tus conjuros conocidos',`<p class="small">Máximo ${d.known} conjuros de nivel 1+ y ${d.cantrips} trucos. Los extras del DM no cuentan. Antes de Secretos mágicos, los conjuros de otras clases requieren una concesión.</p><div class="catalog">${list.map(x=>`<div class="list-row"><div><b>${esc(x.name)}</b><p>${x.level?'Nivel '+x.level:'Truco'} · ${esc(x.source)}${!x.bard?' · otra clase':''}</p></div><select class="control" style="max-width:135px" name="spell-${esc(x.id)}" aria-label="Estado de ${esc(x.name)}"><option value="no">No conocido</option><option value="known" ${state.known.includes(x.id)?'selected':''}>Conocido</option><option value="extra" ${state.extras.includes(x.id)?'selected':''}>Extra del DM</option></select></div>`).join('')}</div>`,fd=>{let k=[],ex=[];for(let sp of list){if(fd.get('spell-'+sp.id)==='known')k.push(sp.id);if(fd.get('spell-'+sp.id)==='extra')ex.push(sp.id);}if(k.filter(id=>spellById(id).level>0).length>d.known||k.filter(id=>spellById(id).level===0).length>d.cantrips)throw Error('Superás el máximo de conjuros o trucos conocidos.');if(state.level<10&&k.some(id=>!spellById(id).bard))throw Error('Ese conjuro de otra clase debe registrarse como Extra del DM.');commit('Repertorio actualizado',s=>{s.known=k;s.extras=ex;if(s.concentration&&!k.includes(s.concentration)&&!ex.includes(s.concentration))s.concentration=null;});});}
function customSpell(id){let source=id?spellById(id):null;let isCustom=source&&state.customSpells.some(x=>x.id===id);modal(source?'Editar referencia del conjuro':'Crear conjuro',`${source&&!isCustom?'<p class="small">Se creará una versión personal de esta referencia, conservando si lo tenías conocido o como extra.</p>':''}<div class="form-grid">${field('Nombre','nombre',source?.name||'','text','required maxlength="150"')}${field('Nivel (0 = truco)','nivel',source?.level??1,'number','min="0" max="9" required')}${select('Tiempo','tiempo',['Acción','Adicional','Reacción','Especial'].map(x=>[x,x]),source?.time||'Acción')}${field('Alcance','alcance',source?.range||'','text','required maxlength="100"')}${field('Componentes','componentes',source?.components||'','text','required maxlength="500"')}${field('Duración','duración',source?.duration||'','text','required maxlength="100"')}</div>${field('Fuente','fuente',source?.source||'DM','text','maxlength="100" required')}${field('Resumen','resumen',source?.brief||'','text','maxlength="1000" required')}${area('Descripción completa','descripción',source?.text||'')}<label class="check"><input name="concentración" type="checkbox" ${source?.concentration?'checked':''}>Concentración</label><label class="check"><input name="ritual" type="checkbox" ${source?.ritual?'checked':''}>Ritual</label><label class="check"><input name="bardo" type="checkbox" ${source?.bard!==false?'checked':''}>Pertenece a la lista de bardo o fue autorizado como selección por el DM.</label>`,fd=>{const newId=isCustom?id:uid();let sp={id:newId,name:String(fd.get('nombre')).trim(),level:number(fd,'nivel',0,9),time:fd.get('tiempo'),range:fd.get('alcance'),components:fd.get('componentes'),duration:fd.get('duración'),source:fd.get('fuente'),brief:fd.get('resumen'),text:fd.get('descripción'),concentration:fd.has('concentración'),ritual:fd.has('ritual'),bard:fd.has('bardo')};commit('Referencia de conjuro: '+sp.name,s=>{if(isCustom)s.customSpells[s.customSpells.findIndex(x=>x.id===id)]=sp;else s.customSpells.push(sp);if(source&&s.known.includes(id)&&(sp.level!==source.level||sp.bard!==source.bard))throw Error('Para cambiar el nivel o la lista, quitá primero el conjuro del repertorio.');if(source&&!isCustom){s.known=s.known.map(x=>x===id?newId:x);s.extras=s.extras.map(x=>x===id?newId:x);if(s.concentration===id)s.concentration=newId;}});toast(source?'Referencia guardada.':'Conjuro creado. Podés elegirlo en Gestionar conjuros.');});}
function rest(){modal('Un respiro en el camino',`<p>Elegí el descanso que completaste.</p><div class="actions">${button('Descanso corto','short-rest','')}${button('Descanso largo','long-rest','secondary')}</div><p class="small section-space">Corto: al menos una hora. Largo: al menos ocho horas y como máximo sus beneficios una vez por 24 horas. La ficha no avanza el tiempo por vos.</p>`);}
function shortRest(){const d=R.stats(state);if(state.hdSpent===null||state.hp===null)throw Error('Confirmá tus PG y Dados de Golpe en Ajustar recursos.');const avail=state.level-state.hdSpent;modal('Descanso corto',`<p class="small">Disponibles: ${avail}d8. Anotá la suma de tus dados físicos o usá «Tirar dados». Canción de descanso se suma una sola vez si gastás al menos un dado.</p><div class="form-grid">${field('Dados de Golpe a gastar','dados',0,'number',`min="0" max="${avail}" required`)}${field('Suma de los d8 (sin CON)','tirada',0,'number','min="0" max="160" required')}${field('Resultado Canción de descanso','canción',0,'number',`min="0" max="${d.songDie}" required`)}</div>${button('Tirar dados seleccionados','short-roll')}<p class="small section-space">Cada d8 suma CON ${sign(d.mods.con)}. ${state.level>=5?'También recuperás Inspiración.':'No recuperás espacios ni Inspiración.'}</p>`,fd=>{const n=number(fd,'dados',0,avail),sum=number(fd,'tirada',n,n*8),song=number(fd,'canción',0,n?d.songDie:0);const heal=n?Math.max(0,sum+n*d.mods.con)+song:0;commit(`Descanso corto: ${n} Dados de Golpe, +${heal} PG`,s=>{s.hdSpent+=n;s.hp=Math.min(d.maxHP,s.hp+heal);if(s.hp>0){s.death={success:0,failure:0};if(heal>0)s.conditions=s.conditions.filter(x=>x!=='Inconsciente');}if(s.level>=5)s.inspirationSpent=0;s.extraResources.forEach(x=>{if(x.reset==='short')x.spent=0;});});});}
function longRest(){if(state.hp===0)throw Error('Para obtener los beneficios del descanso largo debés iniciarlo con al menos 1 PG.');let d=R.stats(state);modal('Descanso largo completado',`<p>Recuperás todos tus PG, espacios e Inspiraciones. Recuperás hasta <b>${Math.max(1,Math.floor(state.level/2))} Dados de Golpe gastados</b>.</p>${state.hdSpent===null?field('Dados de Golpe disponibles antes del descanso','dados','', 'number',`min="0" max="${state.level}" required`):''}<label class="check"><input name="completo" type="checkbox" required>Confirmo que completé un descanso válido y lo inicié con al menos 1 PG.</label><p class="small">Se limpian PG temporales y concentración. Las condiciones se conservan para que revises su duración.</p>`,fd=>commit('Descanso largo completado',s=>{if(s.hdSpent===null)s.hdSpent=s.level-number(fd,'dados',0,s.level);s.hdSpent=Math.max(0,s.hdSpent-Math.max(1,Math.floor(s.level/2)));s.hp=d.maxHP;s.temp=0;s.inspirationSpent=0;s.slotsSpent=Array(9).fill(0);s.reactionUsed=false;s.concentration=null;s.death={success:0,failure:0};s.universalSpent=0;s.infectiousSpent=0;s.extraResources.forEach(x=>{if(x.reset!=='manual')x.spent=0;});}),'Aplicar descanso');}
function itemEdit(id){const x=state.inventory.find(x=>x.id===id);modal(x?'Editar objeto':'Añadir objeto',`${field('Nombre','nombre',x?.name||'','text','required maxlength="200"')}<div class="form-grid">${field('Cantidad','cantidad',x?.qty??1,'number','min="0" max="999999" required')}${select('Categoría','categoría',['Equipo','Armas','Paquete','Consumibles','Transporte','Tesoro','Otro'].map(x=>[x,x]),x?.category||'Equipo')}${field('Peso unitario (lb, opcional)','peso',x?.weight??'','number','min="0" max="999999" step="0.01"')}${field('Ubicación','ubicación',x?.location||'Sin asignar','text','maxlength="200"')}</div>${area('Descripción / propiedades','notas',x?.notes||'')}${x?button('Eliminar objeto','item-delete','danger',`data-id="${esc(x.id)}"`):''}`,fd=>{const obj={id:x?.id||uid(),name:String(fd.get('nombre')).trim(),qty:number(fd,'cantidad',0,999999),category:fd.get('categoría'),notes:fd.get('notas'),location:fd.get('ubicación'),weight:fd.get('peso')===''?null:Number(fd.get('peso'))};if(!obj.name)throw Error('Escribí un nombre.');commit((x?'Editado: ':'Añadido: ')+obj.name,s=>{if(x)s.inventory[s.inventory.findIndex(a=>a.id===x.id)]=obj;else s.inventory.push(obj);});});}
function goldEdit(){modal('Saldo de monedas',`<p class="small">pc cobre · pp plata · pe electro · po oro · ppt platino.</p><div class="form-grid">${[['cp','Cobre'],['sp','Plata'],['ep','Electro'],['gp','Oro'],['pp','Platino']].map(([k,l])=>field(l,k,state.gold[k],'number','min="0" max="99999999" required')).join('')}</div>`,fd=>commit('Saldo de monedas confirmado',s=>{for(let k in s.gold)s.gold[k]=number(fd,k,0,99999999);s.goldConfirmed=true;}));}
function transaction(){modal('Ingreso o gasto',`<div class="form-grid">${select('Movimiento','tipo',[['income','Ingreso'],['expense','Gasto']],'expense')}${field('Cantidad','cantidad','','number','min="0.01" max="999999" step="0.01" required')}${select('Moneda','moneda',[['1','Cobre'],['10','Plata'],['50','Electro'],['100','Oro'],['1000','Platino']],'100')}</div>${field('Motivo','motivo','','text','required maxlength="200"')}<p class="small">Se convierte el saldo total a su equivalente en oro, plata y cobre al registrar el movimiento.</p>`,fd=>{let value=Number(fd.get('cantidad'))*Number(fd.get('moneda'));if(!Number.isFinite(value)||value<=0||Math.abs(value-Math.round(value))>0.00001)throw Error('El importe debe equivaler a una cantidad entera de cobre.');value=Math.round(value);const total=state.gold.cp+10*state.gold.sp+50*state.gold.ep+100*state.gold.gp+1000*state.gold.pp;const next=total+(fd.get('tipo')==='income'?value:-value);if(next<0)throw Error('No alcanza el saldo.');commit(`${fd.get('tipo')==='income'?'Ingreso':'Gasto'}: ${fd.get('cantidad')} ${fd.get('moneda')==='100'?'po':'(moneda elegida)'} · ${fd.get('motivo')}`,s=>{s.gold={pp:0,ep:0,gp:Math.floor(next/100),sp:Math.floor(next%100/10),cp:next%10};s.goldConfirmed=true;});});}
function editStats(){let d=R.stats(state);modal('Características y armadura',`<div class="form-grid">${Object.entries(R.attrs).map(([k,l])=>field(l,k,state.abilities[k],'number','min="1" max="30" required')).join('')}${field('Base de CA (sin DES)','base',state.acBase,'number','min="0" max="40" required')}${field('Otros bonos de CA','bonus',state.acBonus,'number','min="-20" max="30" required')}</div><p class="small">Los cambios de CON ajustan los PG máximos retroactivamente (${state.level} niveles). Conservamos tus PG actuales, limitados al nuevo máximo. La armadura se calcula como base + DES + otros bonos; para armaduras con límite de DES, ajustá el bono manualmente.</p>`,fd=>commit('Características actualizadas',s=>{for(let k in R.attrs)s.abilities[k]=number(fd,k,1,30);s.acBase=number(fd,'base',0,40);s.acBonus=number(fd,'bonus',-20,30);const next=R.stats(s);if(s.hp!==null)s.hp=Math.min(s.hp,next.maxHP);if(s.inspirationSpent!==null)s.inspirationSpent=Math.min(s.inspirationSpent,next.inspirationMax);s.infectiousSpent=Math.min(s.infectiousSpent,next.inspirationMax);}));}
function levelup(){if(state.level>=20)throw Error('Darien ya está en nivel 20.');const next=state.level+1,d=R.stats(state),maxSpell=R.slots[next].length,target=R.known[next],cTarget=next>=10?4:next>=4?3:2;const isASI=[4,8,12,16,19].includes(next),exp=[3,10].includes(next);let cand=R.allSpells(state).filter(x=>x.level<=maxSpell&&!state.extras.includes(x.id)&&(x.bard||next>=10));const recommended={2:'detectmagic',3:'suggestion',4:'invisibility',5:'hypnotic'}[next];const featSummary=R.features({...clone(state),level:next}).filter(([n])=>!R.features(state).some(([old])=>old===n));modal('Bardo nivel '+next,`<p class="small">${R.slots[next].map((n,i)=>n+' espacios Nv. '+(i+1)).join(' · ')}<br>Hasta ${target} conjuros de nivel 1+ y ${cTarget} trucos. Progresión para bardo puro; otras clases se registran manualmente.</p>${featSummary.map(([n,t])=>`<div class="feature"><h3>${esc(n)}</h3><p>${esc(t)}</p></div>`).join('')}<h3 class="section-space">Puntos de golpe</h3>${select('Aumento','método',[['fixed','Valor fijo: 5 + CON'],['rolled','Dado físico: resultado + CON']],'fixed')}${field('Resultado del d8, si tiraste','d8',5,'number','min="1" max="8"')}${isASI?`<h3>Mejora de características</h3>${select('Elección','asi',[['scores','+2 a una o +1 a dos'],['feat','Dote / ajuste manual del DM']],'scores')}<div class="form-grid">${select('Primer +1','a1',Object.entries(R.attrs),'dex')}${select('Segundo +1','a2',Object.entries(R.attrs),'cha')}</div>${field('Dote elegida (si corresponde)','dote','','text','maxlength="150"')}${area('Efectos de la dote para referencia','efectos','')}<p class="small">Las dotes se anotan; sus efectos numéricos particulares se ajustan en Mi ficha.</p>`:''}${next===3?select('Colegio','colegio',[['eloquence','Colegio de la Elocuencia'],['manual','Otro: rasgos manuales']],state.subclass):''}${exp?`<h3>Elegí dos habilidades para Pericia</h3><div class="form-grid">${select('Pericia 1','e1',R.skills.filter(x=>state.proficiencies.includes(x[0])&&!state.expertise.includes(x[0])).map(x=>[x[0],x[1]]),'persuasion')}${select('Pericia 2','e2',R.skills.filter(x=>state.proficiencies.includes(x[0])&&!state.expertise.includes(x[0])).map(x=>[x[0],x[1]]),'insight')}</div>`:''}<h3 class="section-space">Repertorio al nuevo nivel</h3><p class="small">Elegí tus conjuros finales. Podés reemplazar como máximo uno conocido al subir. ${recommended?'Plan previo: '+esc(spellName(recommended))+'.':''} Los regalos del DM se conservan. Si falta una opción, creala antes en Conjuros.</p><div class="catalog">${cand.map(sp=>`<label class="check"><input type="checkbox" name="learned" value="${esc(sp.id)}" ${state.known.includes(sp.id)?'checked':''}><span><b>${esc(sp.name)}</b><br><small>${sp.level?'Nivel '+sp.level:'Truco'}${!sp.bard?' · Secretos mágicos':''}</small></span></label>`).join('')}</div><p class="small section-space">Subir no cuenta como descanso: se conservan los recursos gastados y los PG actuales.</p>`,fd=>{let k=fd.getAll('learned');const counts={level:k.filter(id=>spellById(id).level>0).length,cantrip:k.filter(id=>spellById(id).level===0).length};if(counts.level!==target||counts.cantrip!==cTarget)throw Error(`Elegí exactamente ${target} conjuros de nivel 1+ y ${cTarget} trucos. Para Secretos mágicos elegidos como trucos, registralos luego como referencia adicional y ajustá el repertorio con el DM.`);if(state.known.filter(id=>!k.includes(id)&&spellById(id).level>0).length>1)throw Error('Podés reemplazar como máximo un conjuro conocido al subir.');if(state.known.some(id=>spellById(id).level===0&&!k.includes(id)))throw Error('El reemplazo normal de 2014 no cambia trucos conocidos.');if(next<10&&k.some(id=>!spellById(id).bard))throw Error('Ese conjuro no pertenece a tu lista.');let a=fd.get('e1'),b=fd.get('e2');if(exp&&a===b)throw Error('Elegí dos habilidades distintas para Pericia.');const increase=fd.get('método')==='fixed'?5:number(fd,'d8',1,8);commit('Subida a bardo '+next,s=>{s.level=next;s.hpBase+=Math.max(1,increase+d.mods.con)-d.mods.con;if(isASI){if(fd.get('asi')==='scores'){let x=fd.get('a1'),y=fd.get('a2');s.abilities[x]++;s.abilities[y]++;if(s.abilities[x]>20||s.abilities[y]>20)throw Error('La mejora no puede superar 20.');}else{let name=String(fd.get('dote')).trim();if(!name)throw Error('Escribí la dote elegida.');s.features.push({name,text:String(fd.get('efectos'))||'Efectos pendientes de ajuste manual.'});}}if(exp)s.expertise.push(a,b);if(next===3)s.subclass=fd.get('colegio');s.known=k;s.levelHistory.push({level:next,note:`PG base +${increase}; repertorio actualizado${exp?'; Pericia elegida':''}${isASI?'; mejora de características / dote':''}.`});const nd=R.stats(s);if(s.hp!==null)s.hp=Math.min(s.hp,nd.maxHP);R.slots[next].forEach((n,i)=>{if(!d.slots[i])s.slotsSpent[i]=0;});});toast('Nivel '+next+' aplicado. Tus recursos gastados se conservaron.');},'Confirmar nivel '+next);}
function settings(){modal('Mi ficha',`${field('Nombre','nombre',state.name,'text','required maxlength="100"')}<div class="actions">${button('Ajustar recursos','resources')}${button('Características','stats')}${button('Recurso personalizado','resource-new')}</div><div class="divider"></div><h3>Copias y dispositivos</h3><p class="small">Cada navegador guarda su propia ficha. Exportá un archivo JSON e importalo en el otro dispositivo. Borrar datos del navegador también borra la ficha local. No hay sincronización automática ni cuentas.</p><div class="actions">${button('Exportar JSON','backup','')}${button('Importar JSON','import')}${button('Recuperar copia anterior','recover')}${rawBroken?button('Descargar datos no legibles','raw-backup'):''}</div><div class="divider"></div><p class="small">El nivel actual es ${state.level}. Los PG máximos ${state.hpConfirmed?'fueron confirmados':'están sugeridos con aumento fijo'}. Para impresiones, usá la versión PDF de tu ficha o la función del navegador.</p>${button('Reiniciar ficha','reset','danger')}`,fd=>commit('Nombre actualizado',s=>s.name=String(fd.get('nombre')).trim()));}
function sources(){modal('Reglas y créditos',`<p>Ficha para <b>D&D 5e 2014</b>. Las reglas de mesa del DM prevalecen sobre la referencia. Los cálculos automáticos cubren bardo puro; las dotes, objetos y otras excepciones se registran y ajustan manualmente.</p><p><a href="https://media.wizards.com/2023/downloads/dnd/SRD_CC_v5.1.pdf" target="_blank" rel="noopener">SRD 5.1</a> · <a href="https://www.dndbeyond.com/posts/1371-silvery-barbs-snatch-a-victory-from-the-jaws-of" target="_blank" rel="noopener">Silvery Barbs</a></p><p class="small">Colegio de la Elocuencia: Tasha’s Cauldron of Everything. Comerciante gremial: Manual del Jugador 2014. Referencias resumidas para uso de mesa; el catálogo incluido es una selección, ampliable con conjuros propios.</p><p class="small">This work includes material taken from the System Reference Document 5.1 (“SRD 5.1”) by Wizards of the Coast LLC and available at https://dnd.wizards.com/resources/systems-reference-document. The SRD 5.1 is licensed under the Creative Commons Attribution 4.0 International License available at https://creativecommons.org/licenses/by/4.0/legalcode.</p><p class="small">Ilustraciones creadas para Darien y su compañera. Esta aplicación no envía tus datos a servicios externos.</p>`);}
const actions={
'settings':settings,'resources':editResources,'stats':editStats,'rest':rest,'short-rest':shortRest,'long-rest':longRest,'levelup':levelup,'spell-manage':spellManage,'spell-new':()=>customSpell(),'spell-edit':e=>customSpell(e.dataset.id),'cast':e=>cast(e.dataset.id),'ritual':e=>cast(e.dataset.id,true),'sources':sources,
'backup':()=>{download('darien-voss-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(state,null,2));toast('Copia exportada.');},
'raw-backup':()=>download('darien-datos-por-recuperar.txt',rawBroken||'','text/plain'),
'undo':()=>{if(!history.length)throw Error('No hay cambios para deshacer en esta sesión.');let previous=history.pop(),before=clone(state);state=previous;persist(before);render();toast('Último cambio deshecho.');},
'import':()=>$('#import-file').click(),
'recover':()=>{let raw=localStorage.getItem(BACKUP);if(!raw)throw Error('No hay una copia anterior.');const imported=R.validate(JSON.parse(raw));confirmAction('Recuperar copia anterior','Se reemplaza la ficha abierta. Podés exportarla antes de continuar.',()=>{const before=clone(state);history.push(before);state=imported;rawBroken=null;persist(before);render();toast('Copia anterior recuperada.');});},
'reset':()=>confirmAction('Reiniciar ficha','Volverá a Darien nivel 2 y sus objetos iniciales. Exportá tu ficha si querés conservarla.',()=>{const before=clone(state);history.push(before);state=R.initial();rawBroken=null;persist(before);render();},'Reiniciar'),
'damage':()=>{if(state.hp===null)throw Error('Confirmá primero tus PG actuales.');let n=Number($('#hp-amount').value);if(!Number.isInteger(n)||n<1||n>9999)throw Error('Usá una cantidad de daño válida.');let conc=state.concentration;commit('Daño recibido: '+n,s=>{let rem=Math.max(0,n-s.temp);s.temp=Math.max(0,s.temp-n);if(s.hp===0&&rem>0)s.death.failure=Math.min(3,s.death.failure+1);s.hp=Math.max(0,s.hp-rem);if(s.hp===0){s.concentration=null;if(!s.conditions.includes('Inconsciente'))s.conditions.push('Inconsciente');if(!s.conditions.includes('Derribado'))s.conditions.push('Derribado');}});if(conc&&state.hp>0)toast('Concentración: CON '+sign(R.stats(state).mods.con)+' contra CD '+Math.max(10,Math.floor(n/2))+'. Si fallás, terminá la concentración.');},
'heal':()=>{if(state.hp===null)throw Error('Confirmá primero tus PG actuales.');let n=Number($('#hp-amount').value);if(!Number.isInteger(n)||n<1||n>9999)throw Error('Usá una cantidad de curación válida.');commit('Curación: '+n,s=>{s.hp=Math.min(R.stats(s).maxHP,s.hp+n);if(s.hp>0){s.death={success:0,failure:0};s.conditions=s.conditions.filter(x=>x!=='Inconsciente');}});},
'temp':()=>modal('PG temporales',field('Nuevo valor','temporales',state.temp,'number','min="0" max="9999" required')+'<p class="small">No se suman con otros PG temporales: elegí qué valor conservar.</p>',fd=>commit('PG temporales ajustados',s=>s.temp=number(fd,'temporales',0,9999))),
'pip':e=>{let t=e.dataset.type,i=t==='slot'?Number(e.dataset.index):e.dataset.index,u=poolValue(state,t,i),max=poolMax(state,t,i);if(u===null)return editPool(t,i);let next=u+(Number(e.dataset.pip)<u?-1:1);commit('Uso '+(next>u?'gastado':'recuperado')+': '+(t==='slot'?'espacio Nv. '+(i+1):t==='inspiration'?'Inspiración':t==='hd'?'Dado de Golpe':t),s=>setPool(s,t,i,Math.max(0,Math.min(max,next))));},
'pool-edit':e=>editPool(e.dataset.type,e.dataset.type==='slot'?Number(e.dataset.index):e.dataset.index),
'reaction':()=>commit('Reacción '+(state.reactionUsed?'recuperada':'gastada'),s=>s.reactionUsed=!s.reactionUsed),
'turn':()=>{commit('Inicio de mi turno: reacción disponible',s=>s.reactionUsed=false);toast('Reacción recuperada.');},
'concentration-end':()=>commit('Concentración terminada',s=>s.concentration=null),
'condition':e=>{let c=e.dataset.condition;commit((state.conditions.includes(c)?'Quitada: ':'Añadida: ')+c,s=>{s.conditions=s.conditions.includes(c)?s.conditions.filter(x=>x!==c):[...s.conditions,c];if(['Incapacitado','Inconsciente','Paralizado','Aturdido','Petrificado'].includes(c)&&s.conditions.includes(c))s.concentration=null;});},
'death':e=>commit('Salvación de muerte registrada',s=>{let k=e.dataset.kind;s.death[k]=(s.death[k]+1)%4;}),'death-reset':()=>commit('Salvaciones de muerte reiniciadas',s=>s.death={success:0,failure:0}),
'roll':e=>{if(e.dataset.label==='Iniciativa'&&state.level>=20&&state.inspirationSpent===R.stats(state).inspirationMax)commit('Inspiración superior: recuperada una Inspiración al tirar iniciativa',s=>s.inspirationSpent--);let b=Number(e.dataset.bonus),n=roll(20)[0];commit(`${e.dataset.label}: d20 ${n} ${sign(b)} = ${n+b}`,()=>{});toast(`${e.dataset.label}: ${n} ${sign(b)} = ${n+b}`);},
'skill-roll':e=>{let id=e.dataset.id,n=roll(20)[0],used=state.level>=3&&state.subclass==='eloquence'&&['persuasion','deception'].includes(id)?Math.max(10,n):n,b=R.skillBonus(state,id),name=R.skills.find(x=>x[0]===id)[1];commit(`${name}: d20 ${n}${n!==used?' → 10 (Lengua de plata)':''} ${sign(b)} = ${used+b}`,()=>{});toast(`${name}: ${n!==used?n+' → '+used:used} ${sign(b)} = ${used+b}`);},
'dice':()=>modal('Tirada de dados',`<div class="form-grid">${field('Cantidad','cantidad',1,'number','min="1" max="30" required')}${select('Dado','dado',[4,6,8,10,12,20,100].map(x=>[x,'d'+x]),20)}${field('Modificador','modificador',0,'number','min="-100" max="100" required')}</div>`,fd=>{let a=roll(number(fd,'dado',4,100),number(fd,'cantidad',1,30)),b=number(fd,'modificador',-100,100),sum=a.reduce((x,y)=>x+y,0)+b;commit('Dados: '+a.join(', ')+' '+sign(b)+' = '+sum,()=>{});toast('Resultado: '+sum+' ('+a.join(', ')+' '+sign(b)+')');},'Tirar'),
'spell-open':e=>{location.hash='spells';setTimeout(()=>{let el=document.getElementById('spell-'+e.dataset.id);if(el){el.open=true;el.scrollIntoView({block:'center'});}},20);},
'item-new':()=>itemEdit(),'item-edit':e=>itemEdit(e.dataset.id),'item-delete':e=>confirmAction('Eliminar objeto','Se quitará esta entrada del inventario.',()=>commit('Objeto eliminado',s=>s.inventory=s.inventory.filter(x=>x.id!==e.dataset.id)),'Eliminar'),
'qty':e=>commit('Cantidad de '+state.inventory.find(x=>x.id===e.dataset.id).name+' modificada',s=>{let x=s.inventory.find(x=>x.id===e.dataset.id);x.qty=Math.max(0,Math.min(999999,x.qty+Number(e.dataset.delta)));}),
'gold-edit':goldEdit,'gold-transaction':transaction,
'mule':()=>modal('Tu mula',`${field('Nombre','nombre',state.mule.name,'text','maxlength="100" required')}<div class="form-grid">${field('PG máximos','máximo',state.mule.max,'number','min="1" max="9999" required')}${field('PG actuales','PG',state.mule.hp??'','number','min="0" max="9999" required')}</div>${area('Notas','notas',state.mule.notes)}`,fd=>commit('Mula actualizada',s=>{let max=number(fd,'máximo',1,9999);s.mule={name:fd.get('nombre'),max,hp:number(fd,'PG',0,max),notes:fd.get('notas')};})),
'notes-save':()=>{const txt=$('#journal-notes').value;commit('Notas de sesión guardadas',s=>s.notes=txt);toast('Notas guardadas.');},
'companion':()=>modal('Compañera de viaje',`${field('Nombre','nombre',state.companion.name,'text','maxlength="100" required')}${area('Descripción y notas','notas',state.companion.notes)}`,fd=>commit('Compañera actualizada',s=>s.companion={name:fd.get('nombre'),notes:fd.get('notas')})),
'feature-new':()=>modal('Rasgo personalizado',`${field('Nombre','nombre','','text','maxlength="150" required')}${area('Qué hace y cómo se usa','texto','')}`,fd=>commit('Rasgo añadido',s=>s.features.push({name:fd.get('nombre'),text:fd.get('texto')}))),
'feature-manage':()=>modal('Rasgos personalizados',state.features.map((x,i)=>`<div class="feature">${field('Nombre','name'+i,x.name,'text','required maxlength="150"')}${area('Descripción','text'+i,x.text)}</div>`).join(''),fd=>commit('Rasgos personalizados actualizados',s=>s.features=s.features.map((x,i)=>({name:fd.get('name'+i),text:fd.get('text'+i)})))),
'resource-new':()=>modal('Recurso personalizado',`${field('Nombre','nombre','','text','required maxlength="100"')}${field('Usos máximos','máximo',1,'number','min="1" max="30" required')}${select('Recuperación','recuperación',[['short','Descanso corto o largo'],['long','Descanso largo'],['manual','Manual']],'long')}`,fd=>commit('Recurso personalizado añadido',s=>s.extraResources.push({id:uid(),name:fd.get('nombre'),max:number(fd,'máximo',1,30),spent:0,reset:fd.get('recuperación')}))),
'short-roll':()=>{let form=$('#dialog-form'),n=Number(form.elements.namedItem('dados').value);if(!Number.isInteger(n)||n<0||n>state.level-state.hdSpent)throw Error('Cantidad de dados no válida.');const a=roll(8,n),b=n&&state.level>=2?roll(R.stats(state).songDie)[0]:0;form.elements.namedItem('tirada').value=a.reduce((x,y)=>x+y,0);form.elements.namedItem('canción').value=b;toast('d8: '+(a.join(', ')||'ninguno')+' · Canción: '+b);}
};
document.addEventListener('click',e=>{if(e.target.closest('[data-close]')){$('#modal').close();return;}const el=e.target.closest('[data-action]');if(!el)return;try{actions[el.dataset.action]?.(el);}catch(err){toast(err.message);}});
document.addEventListener('input',e=>{if(e.target.id==='spell-search'){let pos=e.target.selectionStart;query=e.target.value;render();$('#spell-search').focus();$('#spell-search').setSelectionRange(pos,pos);}});
document.addEventListener('change',e=>{if(e.target.id==='spell-filter'){filter=e.target.value;render();}});
$('#import-file').addEventListener('change',async e=>{let file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>2*1024*1024)throw Error('La copia debe pesar menos de 2 MB.');const next=R.validate(JSON.parse(await file.text()));confirmAction('Importar ficha',`Vas a abrir ${next.name}, nivel ${next.level}. Reemplazará la ficha de este navegador; exportá una copia si querés conservarla.`,()=>{const before=clone(state);history.push(before);state=next;rawBroken=null;persist(before);render();toast('Ficha importada.');},'Importar');}catch(err){toast('No se importó: '+err.message);}});
window.addEventListener('hashchange',go);
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){try{state=R.validate(JSON.parse(e.newValue));history=[];render();toast('Ficha actualizada desde otra pestaña.');}catch{toast('No se pudo leer el cambio de otra pestaña. Exportá tu ficha.');}}});
go();
if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').catch(()=>{});
try{if(document.modelContext?.registerTool)document.modelContext.registerTool({name:'read_character_sheet',description:'Read the current Darien character sheet and remaining resources without changing it.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({name:state.name,level:state.level,stats:R.stats(state),hp:state.hp,slotsSpent:state.slotsSpent,inspirationSpent:state.inspirationSpent,known:state.known.map(spellName),extras:state.extras.map(spellName)})});}catch{}
